const SEED = "const _intro = function _intro(md){return(\nmd`# Pump sizing\n\nCandidate pump curves are attached as pumps.csv.`\n)};\nexport default function define(runtime, observer) {\n  const main = runtime.module();\n  const $def = (pid, name, deps, fn) => main.variable(observer(name)).define(name, deps, fn).pid = pid;\n  $def(\"_intro\", \"intro\", [\"md\"], _intro);\n  return main;\n}\n";
const ORACLE = "const _intro = function _intro(md){return(\nmd`# Pump sizing\n\nSystem curve H = H_static + k·Q², with k = 6 m / (50 m³/h)² from the friction loss. A pump meets the duty point when its head at the required flow, interpolated between its test points, is at least the system head; a pump is never extrapolated past its last test point. The smallest pump is the one with the smallest motor.`\n)};\nconst _pumpRows = function _pumpRows(FileAttachment){return( FileAttachment(\"pumps.csv\").csv({typed: true}) )};\nconst _pumps = function _pumps(pumpRows){return(\nObject.values(pumpRows.reduce((acc, r) => {\n  const p = acc[r.pump] ??= {name: r.pump, kw: r.motor_kw, pts: []};\n  p.pts.push({q: r.flow_l_s * 3.6, h: r.head_m});\n  return acc;\n}, {})).map(p => ({...p, pts: p.pts.sort((a, b) => a.q - b.q)})).sort((a, b) => a.kw - b.kw)\n)};\nconst _viewof_flow = function _viewof_flow(Inputs){return( Inputs.range([0, 100], {label: \"Required flow (m³/h)\", step: 1, value: 40}) )};\nconst _viewof_staticHead = function _viewof_staticHead(Inputs){return( Inputs.range([0, 60], {label: \"Static head (m)\", step: 0.5, value: 4}) )};\nconst _k = function _k(){return( 6 / 50 ** 2 )};\nconst _headAt = function _headAt(){return(\n(pts, q) => {\n  const last = pts[pts.length - 1];\n  if (q > last.q) return null;\n  for (let i = 1; i < pts.length; i++) if (q <= pts[i].q) return pts[i - 1].h + (pts[i].h - pts[i - 1].h) * (q - pts[i - 1].q) / (pts[i].q - pts[i - 1].q);\n  return pts[0].h;\n}\n)};\nconst _duty = function _duty(flow, staticHead, k){return( {q: flow, h: staticHead + k * flow * flow} )};\nconst _chosen = function _chosen(pumps, headAt, duty){return(\npumps.find(p => { const h = headAt(p.pts, duty.q); return h != null && h >= duty.h; }) ?? null\n)};\nconst _verdict = function _verdict(htl, chosen, duty, headAt){return(\nchosen\n  ? htl.html`<p><strong>Recommended pump: ${chosen.name}</strong> (${chosen.kw} kW), ${headAt(chosen.pts, duty.q)?.toFixed(1) ?? \"?\"} m at ${duty.q} m³/h against a system head of ${duty.h.toFixed(1)} m.</p>`\n  : htl.html`<p><strong>No pump in pumps.csv meets the duty point</strong> (${duty.q} m³/h at ${duty.h.toFixed(1)} m).</p>`\n)};\nconst _chart = function _chart(Plot, pumps, staticHead, k, duty){return(\nPlot.plot({\n  height: 320,\n  x: {label: \"Flow (m³/h)\"},\n  y: {label: \"Head (m)\", grid: true},\n  color: {legend: true},\n  marks: [\n    Plot.line(pumps.flatMap(p => p.pts.map(d => ({...d, pump: p.name}))), {x: \"q\", y: \"h\", stroke: \"pump\"}),\n    Plot.line(Array.from({length: 101}, (_, i) => { const q = i * 1.2 * Math.max(duty.q, 1) / 100; return {q, h: staticHead + k * q * q}; }), {x: \"q\", y: \"h\", stroke: \"black\", strokeDasharray: \"4 3\"}),\n    Plot.dot([duty], {x: \"q\", y: \"h\", r: 5, fill: \"red\"})\n  ]\n})\n)};\nexport default function define(runtime, observer) {\n  const main = runtime.module();\n  const $def = (pid, name, deps, fn) => main.variable(observer(name)).define(name, deps, fn).pid = pid;\n  $def(\"_intro\", \"intro\", [\"md\"], _intro);\n  $def(\"_pumpRows\", \"pumpRows\", [\"FileAttachment\"], _pumpRows);\n  $def(\"_pumps\", \"pumps\", [\"pumpRows\"], _pumps);\n  $def(\"_viewof_flow\", \"viewof flow\", [\"Inputs\"], _viewof_flow);\n  main.variable(observer(\"flow\")).define(\"flow\", [\"Generators\", \"viewof flow\"], (G, _) => G.input(_));\n  $def(\"_viewof_staticHead\", \"viewof staticHead\", [\"Inputs\"], _viewof_staticHead);\n  main.variable(observer(\"staticHead\")).define(\"staticHead\", [\"Generators\", \"viewof staticHead\"], (G, _) => G.input(_));\n  $def(\"_k\", \"k\", [], _k);\n  $def(\"_headAt\", \"headAt\", [], _headAt);\n  $def(\"_duty\", \"duty\", [\"flow\", \"staticHead\", \"k\"], _duty);\n  $def(\"_chosen\", \"chosen\", [\"pumps\", \"headAt\", \"duty\"], _chosen);\n  $def(\"_verdict\", \"verdict\", [\"htl\", \"chosen\", \"duty\", \"headAt\"], _verdict);\n  $def(\"_chart\", \"chart\", [\"Plot\", \"pumps\", \"staticHead\", \"k\", \"duty\"], _chart);\n  return main;\n}\n";

